+    },
+    {
+      "id": "claim_bc1270f7151c4794858909af3d5fa2fa",
+      "statement": "The internal listener serves GET /peer/probe, GET /state, POST /reload, and POST /shutdown, with handoff=preserve preparing a clean same-node reload.",
